"""Refresh fifteen DE4 source records and identify current-rule authoring work without adoption."""
from copy import deepcopy
from datetime import datetime,timezone
import json
from apply_di7_ap_as_01 import G,R,A,info,encoded
from prepare_ac5_current_interfaces_01 import at

def read(p):return json.loads(p.read_bytes())

def main():
    out=A/'DE4_CURRENT_SOURCE_INTERFACE_AUDIT_01.json';checkfile=A/'DE4_CURRENT_SOURCE_INTERFACE_CHECK_01.json';snapshot=A/'de4-current-source-interface-01'
    assert not any(p.exists() for p in [out,checkfile,snapshot])
    oldp=R/'data/director/spell_proposals/divination_enchantment_rank4.json';old=read(oldp)
    catalogp=R/'data/public/spell_playtests/catalog.json';indexp=R/'data/public/spell_playtests/authored_review_index.json'
    catalog=read(catalogp);byid={s['id']:s for s in catalog['spells']};index=read(indexp);entries={e['id']:e for e in index['entries']}
    checks=[]
    def ck(label,passed):
        checks.append({'name':label,'passed':bool(passed)});assert passed,label
    ck('Current451/397 ordinary memberships',index['authoredCounts']=={'reviewed':451,'pending':397})
    paths=set(old['sourceFiles'])|set(old['currentGoverningDocuments'])|{oldp.relative_to(G).as_posix()}
    docs=['CLASS_PLAYTEST_RULES.md','COSMOLOGY_EPILOGUE_RELIC_NULL_PLAYTEST.md','COSMOLOGY_EPILOGUE_CHARACTER_PLAYTEST.md','LANGUAGE_COMMUNICATION_PLAYTEST.md','DAMAGE_SHARING_PLAYTEST.md','EQUIPMENT_ITEM_PROCEDURES.md','CHARACTER_FOUNDATION_TABLES.md']
    for n in docs:
        p=R/'docs/mechanics'/n
        ck('Current governing source exists '+n,p.is_file());paths.add(p.relative_to(G).as_posix())
    for n in ['EXPEDITION_PART05_PLAYER.md','EXPEDITION_PART05_DIRECTOR.md','EXPEDITION_REVIEW_STATUS.json']:
        p=R/'docs/mechanics/expedition'/n;ck('Current expedition source '+n,p.is_file());paths.add(p.relative_to(G).as_posix())
    for p in [R/'docs/playtest/CLASS_RESOURCE_REFERENCE.md',A/'AC5_EXACT_ACCEPTANCE_05_RECEIPT.json',A/'AC5_EXACT_ACCEPTANCE_05_APPLICATION_CHECK.json',A/'ac6-full-current-review-03-input/CURRENT_REVIEW_INPUT.json',A/'AC6_FULL_CURRENT_REVIEW_03_SUBMISSION_RECEIPT.json']:
        ck('Current integration source '+p.name,p.is_file());paths.add(p.relative_to(G).as_posix())
    class_files=sorted((R/'data/public/class_playtests').glob('*.json'))
    ck('Seventeen public class documents',len(class_files)==17)
    for p in class_files:paths.add(p.relative_to(G).as_posix())
    records=[];original_examples=[]
    for n,rec in enumerate(old['records']):
        ident=rec['spellId'];ck('Exact original/current source '+ident,rec['fullSourceAndCurrentAccessRecord']==byid[ident]);ck('Pending authored status '+ident,entries[ident]['authoredStatus']=='pending-authored-procedure')
        records.append({'spellId':ident,'questionId':rec['questionId'],'completeCurrentSourceAndAccess':deepcopy(byid[ident]),'completeHistoricalProposal':deepcopy(rec),'currentAuthoredIndexEntry':deepcopy(entries[ident]),'sourceRef':{'path':catalogp.relative_to(G).as_posix(),'pointer':f'/spells/{catalog["spells"].index(byid[ident])}'}})
        for j,text in enumerate(rec['workedCases']):original_examples.append({'id':rec['questionId']+'-'+chr(65+j),'spellId':ident,'originalText':text})
    ck('Fifteen unique spell identities',len(records)==len({x['spellId'] for x in records})==15)
    ck('Thirty complete original worked texts',len(original_examples)==30)
    compare_ids=[x['id'] for x in old['completeCurrentCounterparts']]
    compare_ids+=['alignment-purge','alignment-suggestion','alignment-lock','alignment-anchor','banishment','antimagic-field-lesser','greater-dispel','spell-resistance','resonance-barrier','planar-protection','reputation-shield','living-magma','planar-binding','faction-champion','alignment-portal']
    counterparts=[]
    for ident in dict.fromkeys(compare_ids):
        ck('Comparison identity exists '+ident,ident in entries)
        e=entries[ident];p=(indexp.parent/e['procedureFile']).resolve();doc=read(p);card=at(doc,e['wholeCardPointer'])
        paths.add(p.relative_to(G).as_posix())
        counterparts.append({'spellId':ident,'currentIndexEntry':deepcopy(e),'sourceCatalogRecord':deepcopy(byid[ident]),'completeCurrentAuthoredRecord':deepcopy(card),'procedureFileBinding':info(p),'wholeCardPointer':e['wholeCardPointer'],'procedurePointer':e['procedurePointer'],'authoredStatus':e['authoredStatus']})
        ck('Comparison identity resolves '+ident,card.get(e.get('wholeCardIdField','id'))==ident)
        at(doc,e['procedurePointer'])
        if e.get('authoredAcceptanceReceipt'):paths.add(e['authoredAcceptanceReceipt']['path'])
    focused=[]
    for cls,idx in [('druid',27),('warrior',8),('oracle',108),('oracle',111)]:
        p=R/f'data/public/class_playtests/{cls}.json';card=read(p)['cards'][idx]
        focused.append({'class':cls,'pointer':f'/cards/{idx}','binding':info(p),'completeCurrentCard':card})
    current_issues=[]
    def issue(ident,spells,requirement,refs):current_issues.append({'id':ident,'spellIds':spells,'requiredCurrentResolution':requirement,'sourceRefs':refs,'status':'Authoring requirement; no adopted rule change.'})
    def cref(ident):
        c=next(x for x in counterparts if x['spellId']==ident)
        return {'path':c['procedureFileBinding']['path'],'pointer':c['wholeCardPointer']}
    def docref(name,section):return {'path':(R/'docs/mechanics'/name).relative_to(G).as_posix(),'section':section}
    issue('DE4-C01',['fate-reversal'],'The old proposal already acknowledges that adding Fate Reversal to the two-spell Mark Omen/Fate Coin guard is an explicit shared-rule amendment. Inventory every current operational representation/companion dependency and preserve originals. Define exact full-d20 replacement versus a one-die Coin, physical versus digital/source dice, original visibility, perception60/LoE, commitment order and all downstream shared recipients. No silent accepted-source change.',[cref('mark-omen'),cref('fate-coin'),docref('COMBAT_ACTION_PLAYTEST.md','Reaction refresh and actual interrupt ordering')])
    issue('DE4-C02',['seal-vision','fate-reversal'],'Resolve the actual locus for protection of a pending caster-held reroll permission versus protection of the distant roll-generating body/object/local event. Declare the finite rule for damage/healing dice whose generator is an effect rather than a creature. Protection from Scrying is information-only; Seal Vision intentionally proposes broader Divination blocking, including beneficial effects, without universal antimagic. Its own-school same-family exemption needs explicit acceptance.',[cref('protection-from-scrying'),cref('fate-coin'),cref('antimagic-field-lesser')])
    issue('DE4-C03',['seal-vision','aspect-of-insight'],'Resolve body intersection, partial overlap, ongoing buff suppression/resumption, source caster versus recipient entry, local field applications and exact shared-family priority using current accepted antimagic and AC4/AC5 buff geometry. Never infer whole-effect cancellation from remote concentration owner entry. Proposed Seal interactions with pending AC6 Divination Nexus require refresh after actual AC6 acceptance.',[cref('antimagic-field-lesser'),cref('spell-resistance'),cref('alignment-lock')])
    issue('DE4-C04',['aspect-of-insight'],'Bind the temporary INT/WIS score increase and mental-save advantage to actual current class/stat source timing. Work through +2score versus +1modifier, cap20, original above20, stronger overlapping score bonus, no advantage stacking, derived DC changes only when actually dynamic, fixed/snapshotted spellDC/resource boundaries, suppression and downward clamping. Do not invent a dynamic resource maximum or permanent prerequisite.',[docref('CHARACTER_CREATION_PLAYTEST.md','Ability scores, derived values and acquisition'),docref('CHARACTER_FOUNDATION_TABLES.md','Actual class foundations'),cref('spell-resistance')])
    issue('DE4-C05',['locate-creature'],'Resolve continuing identity, disguised/shapechanged targets, undead/construct versus corpse/ended summon, Banishment cells, same-plane range and placement-conflict AnchorReference. The accepted Banishment conflict has a logical source-test anchor and no occupied footprint; a legal remote bearing is not physical occupancy or line of effect. No special cell detection, body creation, universal untargetability or guessed cosmology.',[cref('banishment'),cref('locate-person'),cref('locate-object'),cref('protection-from-scrying')])
    issue('DE4-C06',['faction-secrets','alignment-forecast'],'Replace historical pending-expedition wording with current EX58 faction/reputation authority. Information does not create membership, allied status, standing, permission, doctrine, roster or a hidden personal thought turned into institutional fact. Preserve stable equivalent-query answers; support independent readable facts without identifying a protected absence. Keep concrete player/Director knowledge boundaries.',[cref('faction-divination'),cref('faction-insight'),cref('faction-spy'),cref('reputation-shield'),docref('expedition/EXPEDITION_PART05_PLAYER.md','Current faction/reputation and social boundaries')])
    issue('DE4-C07',['alignment-forecast'],'Forecast each actual effect with current AP-AS-01 then AC4-ALIGN-01 effective-axis ordering. A known future Lock expiry, current underlying Purge, snapshot-only Nexus alignment, unknown axes and changed action intent need finite examples. No moral judgment, universal future knowledge or retroactive change to a prior forecast.',[cref('alignment-purge'),cref('alignment-suggestion'),cref('alignment-lock'),cref('alignment-anchor'),cref('alignment-prediction')])
    issue('DE4-C08',['resonance-divination'],'Preserve exact current shared RP at the resolution checkpoint; actual same-pool temporary RP versus RC/charges/reserves remains source-defined. The reviewed Resonance Sight already gives exact RP; compare actual60ft versus30ft reach and information protection without inventing new rank-exclusive accuracy or new pool. Cost/reaction spending before the read must be real.',[cref('resonance-sight'),cref('resonance-sight-greater'),docref('CLASS_PLAYTEST_RULES.md','Actual resource identities and cast sequence')])
    issue('DE4-C09',['dominate-person','confusion','compulsion'],'Reconcile new same-target controller replacement and hard-control allowances with accepted one-source-character/target/encounter guard: a fresh save success cannot end old control, blocked establishment cannot replace it, and no recast refunds a spent guard. Original companions retain actual owner phase, budget and command reservation; newly accepted Humanoid Champion is not a free independent action engine.',[cref('dominate-beast'),cref('planar-binding'),cref('faction-champion'),docref('ENCHANTMENT_CONTROL_INTEGRATION_PLAYTEST.md','Instruction arbitration and companion bridge')])
    issue('DE4-C10',['dominate-person','compulsion'],'Specify exact one-way order delivery and continuing versus application-only requirements across source/target plane separation, perception loss, unconscious controller and Banishment. No maintenance tether does not automatically grant cross-plane telepathy, knowledge, new orders or unauthorized secrets. Each new order must name an actual delivery permission; retain pending valid orders only within exact source scope.',[cref('planar-binding'),cref('banishment'),docref('LANGUAGE_COMMUNICATION_PLAYTEST.md','Actual communication channels and no implicit senses')])
    issue('DE4-C11',['confusion'],'Give finite neutral d4 behavior and d8 direction/1dN target selections with exact original physical-die/perception/Fate Coin guard. Actual available Action/movement, forced use of voluntary movement, terrain+crawl+squeeze addition, no suicidal route, no paid ability/resource, source timestamp arbitration and no empty-set reroll. A table choosing agency still consumes the already-established hard-control claim.',[cref('fate-coin'),cref('mark-omen'),docref('COMBAT_ACTION_PLAYTEST.md','Actual movement cost and regular-turn budgets')])
    issue('DE4-C12',['mass-pacify'],'Preserve actual attack-only prohibition and post-establishment committed-attack ending, including a miss or suppressed hit. Distinguish no-attack save spells, ongoing damage, free-targeting information, self-inflicted attacks, an attacker who becomes unable to finish and an earlier committed attack. Define cast-local immutable target snapshot and no repeated hostility scan.',[cref('group-pacify'),cref('pacify'),cref('massive-elemental-blast') if any(x['spellId']=='massive-elemental-blast' for x in counterparts) else docref('COMBAT_ACTION_PLAYTEST.md','Attack actions versus nonattack effects')])
    issue('DE4-C13',['erase-emotion'],'Apply exact current operational components rather than words in names: Mooncursed /cards/27 has physical resistance, bite, full-moon bonus and a Howl choice of temporary HP or Frightened; it is not a generic healing/rage record. Oracle Divine Fury /cards/108 keeps its RC cost/nonfear attacks while the actual critical Frightened rider is suppressed; Fury of the Host /cards/111 is not generically a rage state. Distinguish active fear record suppression from preventing new fear outputs and full mixed-activation cost.',[{'path':x['binding']['path'],'pointer':x['pointer']} for x in focused])
    issue('DE4-C14',['phantasmal-killer'],'Define creation-time Null flags for initial and delayed damage per actual caster/recipient root, not one fresh Veil read per later tick. Keep two school/rank access modes, immediate once-per-round Illusion exposure, distinct Enchantment paid damage, fear-only immunity versus psychic immunity and actual Frightened perception. Work through Stable0, later ordinary damage, true death saves before START damage, disappearing finite body and no deferred suppressed pulse.',[cref('living-magma'),docref('COSMOLOGY_EPILOGUE_RELIC_NULL_PLAYTEST.md','Creation-time damage roots and Null lifecycle'),docref('CORE_RESOLUTION_PLAYTEST.md','Death saves, Stable recovery and damage at zero')])
    issue('DE4-C15',['charm-monster','overwhelming-grief'],'Use actual post-defense/pre-temp positive damage event for damage-triggered endings/saves, including pure transferred original roots and prevention versus tempHP. No duplicate post-transfer mitigation or invalid damage claim; Null nonlethal still deals damage and can trigger these effects. Define actual ally recognition separately from faction alliedStatus, hostility and Charmed attitude; no inferred treaty/consent/membership.',[cref('resonance-barrier'),docref('DAMAGE_SHARING_PLAYTEST.md','Root lineage, mitigation, prevention, transfer and tempHP'),docref('COSMOLOGY_EPILOGUE_RELIC_NULL_PLAYTEST.md','Null changes damage endpoints, not damage existence')])
    issue('DE4-C16',['overwhelming-grief','erase-emotion','dominate-person','confusion','phantasmal-killer','charm-monster'],'Bind actual Incapacitated immunities/class exceptions and lost concentration, then regular-END/source-only attached-phase save/pulse schedules. Do not let transition, reordered initiative, vanished owner, extra turn, supp/resumption or forced plane travel reset deadlines or grant another creature turn, Reaction, command, death save or exposure.',[docref('CONDITIONS_PLAYTEST.md','Incapacitated and Frightened actual mechanics'),docref('COMBAT_ACTION_PLAYTEST.md','Start/end absolute and virtual clocks'),cref('faction-champion'),cref('living-magma')])
    # Two concrete acceptance requirements per identity, rather than claiming authored tests already executed.
    case_pairs={
      'fate-reversal':['Advantage [4,17] becomes a full replacement pair [6,9], then a later Coin/Omen request is denied without spending; compare a prior valid one-die Coin that already reserved the common lineage.','Same shared roll affects two recipients; only one protected by Seal Vision. Resolve actual generator protection and all shared consequences without replacing only convenient targets.'],
      'seal-vision':['Willing protected target crosses a10ft antimagic boundary while a Divination buff and independent non-Divination buff remain live; track source-local suppression and unchanged deadlines.','Two overlapping Seal Vision areas and one remote Divination sensor: own family remains operative, protected subject info unavailable, independent surroundings still readable; total cover still applies.'],
      'aspect-of-insight':['INT19/WIS21 receives proposed bonus: INT20/WIS21; actual INT modifier changes while WIS does not; no permanent spell acquisition, score reduction or fictitious RP refill.','Existing higher flat score bonus and mental-save advantage overlap; establish exact current values, suppress each source separately, and distinguish fixed cast DC from a new cast using actual current stats.'],
      'locate-creature':['Same identity within5miles behind stone produces only direction; compare corpse, genuinely ended summon and actual Banishment cell giving No Bearing without reason.','Accepted Banishment placement conflict supplies a fixed AnchorReference at a known source plane with no footprint; adjudicate bearing by the real remote-sense scope, without fabricating a body or line of sight.'],
      'faction-secrets':['Known faction has one established nonpublic warehouse policy plus a protected officer thought; identify stable one-fact selection and unchanged repeated-query answer.','Faction is known but no responsive secret is authored; Indeterminate creates no roster, membership, standing, permission, alignment or invented secret.'],
      'alignment-forecast':['Underlying LawfulEvil, active NeutralGood Lock and known expiry before an intended ward crossing: evaluate current AP-AS/AC4 priority with an actual action clock.','Required alignment axis or future choice is undefined; Indeterminate remains distinct from a known Unaffected result and reveals no hidden faction/plane identity.'],
      'resonance-divination':['Current RP12; an actual legal Reaction spends3 before read; return9, exclude an independently recorded RC5/itemcharge2 and show genuine zero distinct from missing pool.','Compare actual30ft cantrip read and60ft rank4 read against Protection from Scrying/Seal Vision; exactness overlap is stated without silently changing either rank or effect.'],
      'dominate-person':['A Humanoid Champion has only its original-owner attached phase and one reserved command; test redirected legal ordinary attack versus no-owner-command and another-companion-reservation cases.','Same controller already spent its target encounter hard guard; replacement cast is saved/blocked versus genuinely established by a different eligible source; preserve old controller unless replacement actually establishes.'],
      'mass-pacify':['Target is pacified; a later legal attack is committed then misses or is suppressed, ending only relevant applications; contrast a previous ongoing nonattack damage tick.','Pacified target casts an actually permitted saving-throw damage spell without an attack roll; target-set capture and attack-only wording neither invent friendliness nor a universal harm ban.'],
      'confusion':['Finite visible candidates sorted by existing identity, physicald4 selects attack then actual1dN chooses ally; show coin timing/guards and no reroll when no legal candidates.','d4 direction branch on difficult terrain while squeezing uses actual additive movement; already-spent movement and another instruction leave no second budget or unsafe fall.'],
      'erase-emotion':['Mooncursed chooses temporary-HP Howl while fear output is prohibited; actual Form Surge/BufferReserve and per-shift usage remain, with no generic form shutdown.','Oracle Divine Fury actual critical: weapon/nonfear bonuses resolve, fear rider suppressed, full2RC was paid; an independent previously inflicted fear continues its own record and clock.'],
      'compulsion':['TargetSpeed30 already partly spent before a conflicting instruction opportunity; direction is fixed, actual safe path consumes only legal remaining budget and expires even blocked.','An owner-attached companion has no supplied movement command/phase; compulsory wording creates no ownerBA, extra phase, teleport, support or resource.'],
      'phantasmal-killer':['Initial Illusion damage root created with active Null Veil, caster purged afterward, later scheduled damage retains original root; an independently new Enchantment cast evaluates current state.','Death-save-eligible target starts Dying at0, makes real START death save before periodic packet, and faces one earliest-eligible Illusion pulse across two applications; compare fear-only immunity/psychic immunity and lost suppressed tick.'],
      'charm-monster':['Hit consumes pure Resonance Barrier prevention before tempHP; zero post-defense packet gives no damage save, while positive packet fully paid by tempHP still gives the stated save.','Two casters with distinct Charmed relations and only one actually recognized ally source of damage: track separate save/end results and unchanged memories, consent and actual standing.'],
      'overwhelming-grief':['Actual Incapacitated would end concentration; exact immunity blocks establishment and consumes no invented fallback, while a later legal positive Null hit ends established grief without restoring concentration.','Source-only END saves on a temporarily absent companion phase preserve fixed six-second schedule and original deadline; no death save, recharge, command or immediate transition retry is created.']}
    required=[]
    for ident,pair in case_pairs.items():
        for j,text in enumerate(pair):required.append({'id':f'DE4-N{len(required)+1:02}','spellId':ident,'requiredScenario':text,'status':'Required future fully worked source-linked case, not an executed test or adopted rule.'})
    ck('Thirty new explicit case requirements',len(required)==30)
    source_changes=[]
    for path,prior in old['sourceFiles'].items():
        current=info(G/path)
        if any(current[k]!=prior[k] for k in ['bytes','sha256']):source_changes.append({'path':path,'historicalBinding':prior,'currentBinding':current,'meaning':'Original proposal remains preserved; this comparison does not silently replace its historical source text.'})
    bindings=[info(G/p) for p in sorted(paths)]
    for ref in [r for i in current_issues for r in i['sourceRefs']]:
        p=G/ref['path'];ck('Issue source exists '+ref['path'],p.is_file());ck('Issue source bound '+ref['path'],ref['path'] in paths)
        if ref.get('pointer'):at(read(p),ref['pointer']);ck('Issue JSON pointer resolves '+ref['pointer'],True)
    snapshot.mkdir()
    for b in bindings:
        p=G/b['path'];q=snapshot/'sources'/b['path'];q.parent.mkdir(parents=True,exist_ok=True);q.write_bytes(p.read_bytes());ck('Frozen source exact '+b['path'],p.read_bytes()==q.read_bytes())
    result={'id':'DE4-CURRENT-SOURCE-INTERFACE-AUDIT-01','recordedAtUtc':datetime.now(timezone.utc).isoformat(),'status':'Complete current source/interface audit for15 pending procedures. Unsent and unadopted; procedure completion and actual GPT review remain.','historicalProposal':info(oldp),'currentOrdinaryCounts':index['authoredCounts'],'records':records,'originalExamplesUnchanged':original_examples,'historicalIssuesUnchanged':old['explicitJointIssues'],'historicalSharedProposalUnchanged':old['sharedProposal'],'currentCounterparts':counterparts,'focusedCurrentClassCards':focused,'all17ClassBindings':[info(p) for p in class_files],'currentReviewIssues':current_issues,'requiredNewExamples':required,'sourceChangesSinceHistoricalProposal':source_changes,'sourceBindings':bindings,'pendingAc6Dependency':{'input':info(A/'ac6-full-current-review-03-input/CURRENT_REVIEW_INPUT.json'),'submission':info(A/'AC6_FULL_CURRENT_REVIEW_03_SUBMISSION_RECEIPT.json'),'rule':'Actual GPT review in progress; pending AC6 drafts are comparison evidence, never accepted authority. Refresh after acceptance before DE4 joint submission.'},'newSpellAdoptions':0,'runtimeTestsExecuted':0,'humanPlaytested':False,'sourceInformationDeleted':0}
    out.write_bytes(encoded(result));(snapshot/'SOURCE_MANIFEST.json').write_bytes(encoded({'bindings':bindings}))
    checkfile.write_bytes(encoded({'id':'DE4-CURRENT-SOURCE-INTERFACE-CHECK-01','audit':info(out),'checks':checks,'checkCount':len(checks),'failureCount':0,'sourceFiles':len(bindings),'spellIdentities':15,'placements':sum(len(x['completeCurrentSourceAndAccess']['source']['original']['placements']) for x in records),'historicalExamples':30,'currentComparisons':len(counterparts),'currentIssues':len(current_issues),'requiredNewExamples':len(required),'status':'Preservation/reference/inventory checks only; no full semantic approval, rule adoption, runtime test or human playtest.'}))
    print(json.dumps({'audit':info(out),'check':info(checkfile),'sources':len(bindings),'comparisons':len(counterparts),'issues':len(current_issues),'checks':len(checks),'failures':0}))

if __name__=='__main__':main()
